"""TaskScheduler: event-driven scheduler with wildcard pub/sub and O(1) min/max stack."""

from __future__ import annotations

import fnmatch
from dataclasses import dataclass, field
from typing import Any, Callable


@dataclass
class _MinMaxStack:
    """Internal stack that tracks min and max in O(1)."""

    _items: list[Any] = field(default_factory=list)
    _min_stack: list[Any] = field(default_factory=list)
    _max_stack: list[Any] = field(default_factory=list)

    def push(self, value: Any) -> None:
        self._items.append(value)
        if not self._min_stack or value <= self._min_stack[-1]:
            self._min_stack.append(value)
        if not self._max_stack or value >= self._max_stack[-1]:
            self._max_stack.append(value)

    def pop(self) -> Any:
        if not self._items:
            raise IndexError("pop from empty stack")
        value = self._items.pop()
        if value == self._min_stack[-1]:
            self._min_stack.pop()
        if value == self._max_stack[-1]:
            self._max_stack.pop()
        return value

    def top(self) -> Any:
        if not self._items:
            raise IndexError("top from empty stack")
        return self._items[-1]

    def get_min(self) -> Any:
        if not self._min_stack:
            raise IndexError("get_min from empty stack")
        return self._min_stack[-1]

    def get_max(self) -> Any:
        if not self._max_stack:
            raise IndexError("get_max from empty stack")
        return self._max_stack[-1]

    def __len__(self) -> int:
        return len(self._items)

    def __bool__(self) -> bool:
        return bool(self._items)


class TaskScheduler:
    """Event-driven task scheduler with wildcard pub/sub and O(1) min/max retrieval.

    Supports two concerns:
    - **Event system**: subscribe listeners to event patterns (with ``*`` / ``**``
      wildcards) and emit events that fan out to all matching listeners.
    - **Task stack**: push, pop, top, getMin, getMax on a priority-ordered stack,
      all in O(1) time via auxiliary min/max tracking stacks.

    Examples
    --------
    >>> scheduler = TaskScheduler()
    >>> scheduler.subscribe("task.*", lambda evt, data: print(f"got {evt}"))
    >>> scheduler.push(5)
    >>> scheduler.push(2)
    >>> scheduler.getMin()
    2
    >>> scheduler.emit("task.created", {"id": 1})
    got task.created
    """

    def __init__(self) -> None:
        self._stack = _MinMaxStack()
        self._listeners: dict[str, list[Callable[[str, Any], None]]] = {}

    # ── Event system ────────────────────────────────────────────────

    def subscribe(self, pattern: str, callback: Callable[[str, Any], None]) -> None:
        """Register *callback* for events matching *pattern*.

        Patterns use ``fnmatch``-style wildcards:
        - ``*``  matches everything *within* a single segment (e.g. ``task.*``)
        - ``**`` is not special here; use ``*`` at the top level for "all events".

        Parameters
        ----------
        pattern:
            Event name or glob pattern (e.g. ``"task.*"``, ``"*"``).
        callback:
            A callable ``(event_name: str, data: Any) -> None``.
        """
        self._listeners.setdefault(pattern, []).append(callback)

    def unsubscribe(self, pattern: str, callback: Callable[[str, Any], None]) -> None:
        """Remove a previously registered *callback* from *pattern*.

        Raises ``ValueError`` if the callback is not found.
        """
        listeners = self._listeners.get(pattern)
        if listeners is None:
            raise ValueError(f"No listeners for pattern '{pattern}'")
        listeners.remove(callback)
        if not listeners:
            del self._listeners[pattern]

    def emit(self, event: str, data: Any = None) -> None:
        """Emit an *event*, invoking every callback whose pattern matches.

        Matching uses ``fnmatch.fnmatchcase`` so ``"task.*"`` matches
        ``"task.created"`` but not ``"task.sub.created"``.

        Parameters
        ----------
        event:
            The event name (e.g. ``"task.created"``).
        data:
            Arbitrary payload forwarded to each matching callback.
        """
        for pattern, listeners in self._listeners.items():
            if fnmatch.fnmatchcase(event, pattern):
                for callback in listeners:
                    callback(event, data)

    # ── Min/max stack (O(1) per operation) ──────────────────────────

    def push(self, value: Any) -> None:
        """Push *value* onto the task stack. O(1).

        Emits ``"stack.push"`` with ``{"value": value}``.
        """
        self._stack.push(value)
        self.emit("stack.push", {"value": value})

    def pop(self) -> Any:
        """Pop and return the top value. O(1).

        Emits ``"stack.pop"`` with ``{"value": <popped>}``.

        Raises ``IndexError`` if the stack is empty.
        """
        value = self._stack.pop()
        self.emit("stack.pop", {"value": value})
        return value

    def top(self) -> Any:
        """Return the top value without removing it. O(1).

        Raises ``IndexError`` if the stack is empty.
        """
        return self._stack.top()

    def getMin(self) -> Any:
        """Return the minimum value currently in the stack. O(1).

        Raises ``IndexError`` if the stack is empty.
        """
        return self._stack.get_min()

    def getMax(self) -> Any:
        """Return the maximum value currently in the stack. O(1).

        Raises ``IndexError`` if the stack is empty.
        """
        return self._stack.get_max()

    def __len__(self) -> int:
        return len(self._stack)

    def __bool__(self) -> bool:
        return bool(self._stack)
